-- Esquema para la futura integración Oracle; no se ejecuta en modo dummy.
CREATE TABLE CLIENTES (ID NUMBER(19) PRIMARY KEY, NUMERO VARCHAR2(40) NOT NULL UNIQUE, DOCUMENTO VARCHAR2(40) NOT NULL UNIQUE, NOMBRE VARCHAR2(200) NOT NULL, CONTACTO VARCHAR2(200), ESTADO VARCHAR2(20) NOT NULL);
CREATE TABLE CUENTAS (ID NUMBER(19) PRIMARY KEY, CLIENTE_ID NUMBER(19) NOT NULL REFERENCES CLIENTES(ID), NUMERO VARCHAR2(40) NOT NULL UNIQUE, TIPO VARCHAR2(40) NOT NULL, MONEDA VARCHAR2(3) NOT NULL, SALDO NUMBER(19,2) NOT NULL, ESTADO VARCHAR2(20) NOT NULL);
CREATE TABLE MOVIMIENTOS (ID NUMBER(19) PRIMARY KEY, CUENTA_ID NUMBER(19) NOT NULL REFERENCES CUENTAS(ID), TIPO VARCHAR2(20) NOT NULL, IMPORTE NUMBER(19,2) NOT NULL, FECHA_OPERATIVA DATE NOT NULL, CONCEPTO VARCHAR2(500), ESTADO VARCHAR2(20) NOT NULL, USUARIO VARCHAR2(100) NOT NULL, FECHA_HORA TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE CIERRES_DIARIOS (ID NUMBER(19) PRIMARY KEY, FECHA_OPERATIVA DATE NOT NULL UNIQUE, ESTADO VARCHAR2(20) NOT NULL, TOTAL_DEBITOS NUMBER(19,2), TOTAL_CREDITOS NUMBER(19,2), MOTIVO_ERROR VARCHAR2(1000));
